        Scanner scanner = new Scanner(System.in);
        int maxSize = 2005;
        int mod = 1000000007;
        int[][] dp = new int[maxSize][maxSize];
        int[][] ok = new int[maxSize][maxSize];
        ok[0][0] = 1;
        for (int i = 1; i < maxSize; i++) {
            for (int j = i & 1; j <= i; j += 2) {
